package ma.ebank.ebank; import org.springframework.stereotype.Service; import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry; import feign.FeignException; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service public class CustomerLookup { private final CustomerClient client; private final CircuitBreakerRegistry registry; public CustomerLookup(CustomerClient c,CircuitBreakerRegistry r){client=c;registry=r;}
public CustomerClient.CustomerView find(Long id){try{return registry.circuitBreaker("customer").executeSupplier(()->{try{return client.find(id);}catch(FeignException.NotFound e){return null;}});}catch(RuntimeException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Customer Service indisponible",e);}} }